import React from 'react';
import { Link } from 'react-router-dom';
import { Heart, MapPin, Maximize2, BedDouble, CheckCircle } from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import { useSaved } from '../context/SavedContext';
import styles from './PropertyCard.module.css';

export default function PropertyCard({ property: p, onEnquire }) {
  const { user } = useAuth();
  const { isSaved, toggle } = useSaved();
  const saved = isSaved(p.id || p._id);

  const handleSave = (e) => {
    e.preventDefault();
    if (!user) { alert('Please log in to save properties.'); return; }
    toggle(p);
  };

  const handleEnquire = (e) => {
    e.preventDefault();
    onEnquire?.(p);
  };

  return (
    <Link to={`/property/${p.id || p._id}`} className={styles.card}>
      {/* Image */}
      <div className={styles.media}>
        <img
          src={p.image || (p.images?.[0]) || 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=800&q=80'}
          alt={p.title}
          className={styles.img}
          loading="lazy"
        />

        {/* Badges */}
        <div className={styles.badgeRow}>
          {(p.badges || []).slice(0, 2).map((b, i) => (
            <span key={i} className={`${styles.badge} ${styles['badge_' + (b.variant || 'sage')]}`}>
              {b.label}
            </span>
          ))}
        </div>

        {/* Verified */}
        <div className={styles.verified}>
          <CheckCircle size={12} />
          <span>Verified</span>
        </div>

        {/* Save button */}
        <button className={`${styles.saveBtn} ${saved ? styles.saveBtnActive : ''}`} onClick={handleSave} aria-label="Save">
          <Heart size={16} fill={saved ? '#e11d48' : 'none'} color={saved ? '#e11d48' : '#0F172A'} />
        </button>

        {/* Possession */}
        {p.possession && <div className={styles.possession}>{p.possession}</div>}
      </div>

      {/* Body */}
      <div className={styles.body}>
        <div className={styles.priceRow}>
          <span className={styles.price}>{p.price}</span>
          {p.perSqft && <span className={styles.perSqft}>{p.perSqft}</span>}
        </div>

        <div className={styles.title}>{p.title}</div>

        <div className={styles.location}>
          <MapPin size={13} />
          <span>{p.location}</span>
        </div>

        <div className={styles.specs}>
          {p.bedroom && (
            <span className={styles.spec}>
              <BedDouble size={13} />
              {p.bedroom.includes('BHK') ? p.bedroom : `${p.bedroom} BHK`}
            </span>
          )}
          {(p.plotSize || p.area) && (
            <span className={styles.spec}>
              <Maximize2 size={12} />
              {p.plotSize || p.area}
            </span>
          )}
        </div>

        <div className={styles.actions}>
          <span className={styles.detailsBtn}>View Details</span>
          {p.secondaryCta && (
            <button className={styles.enquireBtn} onClick={handleEnquire}>
              {p.secondaryCta.label || 'Enquire'}
            </button>
          )}
        </div>
      </div>
    </Link>
  );
}
